//! Matched Highway C-ABI versus DiskANN 0.60.0 production distance-provider benchmark.
//! No SQLite, allocation, normalization, or input generation occurs in timed loops.
#![deny(unsafe_op_in_unsafe_fn)]

use std::ffi::{c_char, CStr};
use std::fs::OpenOptions;
use std::hint::black_box;
use std::io::{Seek, SeekFrom, Write};
use std::time::{Duration, Instant};

use diskann_vector::distance::{Distance, DistanceProvider, Metric};
use serde_json::{json, Value};

// Link exactly the production C++ objects generated by vectorlite/build.rs.
#[link(name = "vectorlite_core", kind = "static")]
#[cfg_attr(target_os = "macos", link(name = "c++"))]
#[cfg_attr(target_os = "linux", link(name = "stdc++"))]
extern "C" {
    fn vl_ops_l2_sq_f32(a: *const f32, b: *const f32, n: usize) -> f32;
    fn vl_ops_ip_dist_f32(a: *const f32, b: *const f32, n: usize) -> f32;
    fn vl_ops_normalize_f32(a: *mut f32, n: usize);
    fn vl_ops_best_target() -> *const c_char;
}
#[link(name = "hwy", kind = "static")]
extern "C" {}

#[derive(Clone, Copy, Debug)]
enum Kind {
    L2,
    Cosine,
}
impl Kind {
    fn name(self) -> &'static str {
        match self {
            Self::L2 => "l2_squared",
            Self::Cosine => "cosine_normalized",
        }
    }
    fn native(self, dim: usize) -> Distance<f32, f32> {
        f32::distance_comparer(
            match self {
                Self::L2 => Metric::L2,
                Self::Cosine => Metric::CosineNormalized,
            },
            Some(dim),
        )
    }
    fn highway(self, a: &[f32], b: &[f32]) -> f32 {
        assert_eq!(a.len(), b.len());
        // SAFETY: Both typed slices are live, f32-aligned, and have equal lengths.
        // These are the same C ABI functions used by vectorlite/src/ops.rs.
        unsafe {
            match self {
                Self::L2 => vl_ops_l2_sq_f32(a.as_ptr(), b.as_ptr(), a.len()),
                Self::Cosine => vl_ops_ip_dist_f32(a.as_ptr(), b.as_ptr(), a.len()),
            }
        }
    }
    fn oracle(self, a: &[f32], b: &[f32]) -> f64 {
        match self {
            Self::L2 => a
                .iter()
                .zip(b)
                .map(|(&a, &b)| (f64::from(a) - f64::from(b)).powi(2))
                .sum(),
            Self::Cosine => {
                1.0 - a
                    .iter()
                    .zip(b)
                    .map(|(&a, &b)| f64::from(a) * f64::from(b))
                    .sum::<f64>()
            }
        }
    }
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
    fn value(&mut self) -> f32 {
        ((self.next() >> 40) as f32 / 8_388_608.0) - 1.0
    }
}

struct Matrix {
    storage: Vec<f32>,
    start: usize,
    stride: usize,
    dim: usize,
    count: usize,
}
impl Matrix {
    fn new(dim: usize, count: usize, offset: usize) -> Self {
        let stride = dim.div_ceil(16) * 16;
        let storage = vec![0.0; count * stride + 32];
        let address = storage.as_ptr() as usize;
        let start = (64 - address % 64) % 64 / 4 + offset;
        assert_eq!((address + start * 4) % 64, offset * 4);
        Self {
            storage,
            start,
            stride,
            dim,
            count,
        }
    }
    fn row(&self, index: usize) -> &[f32] {
        let start = self.start + index * self.stride;
        &self.storage[start..start + self.dim]
    }
    fn row_mut(&mut self, index: usize) -> &mut [f32] {
        let start = self.start + index * self.stride;
        &mut self.storage[start..start + self.dim]
    }
    fn fill(&mut self, rng: &mut Rng, kind: Kind) {
        for i in 0..self.count {
            let row = self.row_mut(i);
            for value in row.iter_mut() {
                *value = rng.value();
            }
            if matches!(kind, Kind::Cosine) {
                // SAFETY: The mutable slice is a complete, aligned f32 vector.
                // Normalize once outside timing using vectorlite's production path.
                unsafe { vl_ops_normalize_f32(row.as_mut_ptr(), row.len()) };
            }
        }
    }
}

#[derive(Default)]
struct Checks {
    comparisons: usize,
    bit_mismatches: usize,
    max_pair_abs_error: f64,
    max_highway_oracle_abs_error: f64,
    max_diskann_oracle_abs_error: f64,
}
impl Checks {
    fn check(&mut self, kind: Kind, native: &Distance<f32, f32>, a: &[f32], b: &[f32]) {
        let h = kind.highway(a, b);
        let d = native.call(a, b);
        let oracle = kind.oracle(a, b);
        assert!(h.is_finite() && d.is_finite() && oracle.is_finite());
        let he = (f64::from(h) - oracle).abs();
        let de = (f64::from(d) - oracle).abs();
        // Mixed absolute/relative tolerance also handles near-zero/self distances.
        let tolerance = 2e-6 * oracle.abs().max(1.0);
        assert!(he <= tolerance, "Highway error {he} > {tolerance}");
        assert!(de <= tolerance, "DiskANN error {de} > {tolerance}");
        self.comparisons += 1;
        self.bit_mismatches += usize::from(h.to_bits() != d.to_bits());
        self.max_pair_abs_error = self
            .max_pair_abs_error
            .max((f64::from(h) - f64::from(d)).abs());
        self.max_highway_oracle_abs_error = self.max_highway_oracle_abs_error.max(he);
        self.max_diskann_oracle_abs_error = self.max_diskann_oracle_abs_error.max(de);
    }
    fn json(&self) -> Value {
        json!({
            "comparisons": self.comparisons,
            "bit_mismatches": self.bit_mismatches,
            "max_pair_abs_error": self.max_pair_abs_error,
            "max_highway_oracle_abs_error": self.max_highway_oracle_abs_error,
            "max_diskann_oracle_abs_error": self.max_diskann_oracle_abs_error,
            "oracle_tolerance": "2e-6 * max(1, abs(float64 reference))"
        })
    }
}

// The generic closure is monomorphized: no added common function-pointer trampoline.
// Black-box both slices on EVERY call, preventing input hoisting/constant folding.
// Native retains its real provider indirect call; Highway retains its C ABI/dispatch.
fn timed(
    query: &[f32],
    corpus: &Matrix,
    order: &[usize],
    rounds: usize,
    mut distance: impl FnMut(&[f32], &[f32]) -> f32,
) -> (f64, f64) {
    let mut checksum = 0.0f64;
    let start = Instant::now();
    for _ in 0..rounds {
        for &i in order {
            let value = distance(black_box(query), black_box(corpus.row(i)));
            checksum += f64::from(black_box(value));
        }
    }
    let seconds = start.elapsed().as_secs_f64();
    black_box(checksum);
    assert!(checksum.is_finite());
    (seconds, checksum)
}

fn median(values: impl IntoIterator<Item = f64>) -> f64 {
    let mut values: Vec<_> = values.into_iter().collect();
    values.sort_by(f64::total_cmp);
    let n = values.len();
    if n % 2 == 0 {
        (values[n / 2 - 1] + values[n / 2]) / 2.0
    } else {
        values[n / 2]
    }
}

fn input_fingerprint(query: &[f32], corpus: &Matrix, order: &[usize]) -> String {
    // Stable non-cryptographic identity of actual logical f32 inputs and visit order.
    let mut hash = 0xcbf29ce484222325u64;
    for word in query
        .iter()
        .chain((0..corpus.count).flat_map(|i| corpus.row(i)))
        .map(|value| u64::from(value.to_bits()))
        .chain(order.iter().map(|&i| i as u64))
    {
        for byte in word.to_le_bytes() {
            hash = (hash ^ u64::from(byte)).wrapping_mul(0x100000001b3);
        }
    }
    format!("{hash:016x}")
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut output = None;
    let mut pairs = 7usize;
    let mut milliseconds = 75u64;
    let mut dimensions = vec![32usize, 128, 129, 384, 768, 1536, 3000];
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--output" => output = Some(args.next().ok_or("missing output path")?),
            "--pairs" => pairs = args.next().ok_or("missing pairs")?.parse()?,
            "--milliseconds" => {
                milliseconds = args.next().ok_or("missing milliseconds")?.parse()?
            }
            "--dimensions" => {
                dimensions = args
                    .next()
                    .ok_or("missing dimensions")?
                    .split(',')
                    .map(str::parse)
                    .collect::<Result<_, _>>()?;
            }
            // Cargo bench may supply this flag even for harness=false.
            "--bench" => {}
            _ => return Err(format!("unknown argument {arg}").into()),
        }
    }
    if pairs == 0 || pairs > 100 || milliseconds == 0 || milliseconds > 10_000 {
        return Err("pairs must be 1..100 and milliseconds 1..10000".into());
    }
    if dimensions.is_empty() || dimensions.iter().any(|&d| d == 0 || d > 3000) {
        return Err("dimensions must be in 1..3000".into());
    }
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(output.ok_or("--output NEW_JSON_PATH is required")?)?;
    // SAFETY: Production Highway shim returns a non-null static NUL-terminated name.
    let target = unsafe { CStr::from_ptr(vl_ops_best_target()) }.to_str()?;
    let mut report = json!({
        "schema_version": 1,
        "status": "running",
        "architecture": std::env::consts::ARCH,
        "os": std::env::consts::OS,
        "highway_target": target,
        "diskann_version": "0.60.0",
        "compiled_neon": cfg!(target_feature = "neon"),
        "compiled_dotprod": cfg!(target_feature = "dotprod"),
        "native_api": "f32::distance_comparer(metric, Some(dimension)).call(a,b)",
        "pairs": pairs,
        "minimum_sample_milliseconds": milliseconds,
        "seed": 42,
        "cases": [],
    });
    let persist = |file: &mut std::fs::File, report: &Value| -> std::io::Result<()> {
        file.seek(SeekFrom::Start(0))?;
        serde_json::to_writer_pretty(&mut *file, report)?;
        file.write_all(b"\n")?;
        let length = file.stream_position()?;
        file.set_len(length)?;
        file.flush()
    };
    persist(&mut file, &report)?;
    for dim in dimensions {
        for kind in [Kind::L2, Kind::Cosine] {
            for offset in [0usize, 1] {
                for count in [16usize, 4096] {
                    let mut rng = Rng(42);
                    let mut query = Matrix::new(dim, 1, offset);
                    let mut corpus = Matrix::new(dim, count, offset);
                    query.fill(&mut rng, kind);
                    corpus.fill(&mut rng, kind);
                    let mut order: Vec<_> = (0..count).collect();
                    for i in (1..count).rev() {
                        let j = rng.next() as usize % (i + 1);
                        order.swap(i, j);
                    }
                    let native = kind.native(dim);
                    let q = query.row(0);
                    let mut checks = Checks::default();
                    for i in 0..count {
                        checks.check(kind, &native, q, corpus.row(i));
                    }
                    checks.check(kind, &native, q, q);
                    let opposite: Vec<_> = q.iter().map(|v| -v).collect();
                    checks.check(kind, &native, q, &opposite);
                    let mut near = q.to_vec();
                    near[0] += 1e-6;
                    checks.check(kind, &native, q, &near);
                    // Match real cosine inputs: normalization itself is not timed.
                    let zero = vec![0.0; dim];
                    checks.check(kind, &native, &zero, &zero);
                    // Warm up both paths and choose the SAME operation count, long
                    // enough for the faster path to meet the target duration.
                    let mut rounds = 1usize;
                    let target = Duration::from_millis(milliseconds).as_secs_f64();
                    loop {
                        let (h, _) = timed(q, &corpus, &order, rounds, |a, b| kind.highway(a, b));
                        let (d, _) = timed(q, &corpus, &order, rounds, |a, b| native.call(a, b));
                        if h.min(d) >= target {
                            break;
                        }
                        let factor = (target / h.min(d).max(1e-9) * 1.1).ceil() as usize;
                        rounds = rounds
                            .checked_mul(factor.clamp(2, 100))
                            .ok_or("round overflow")?;
                    }
                    let operations = rounds * count;
                    let mut samples = Vec::new();
                    let mut ratios = Vec::new();
                    let mut hs = Vec::new();
                    let mut ds = Vec::new();
                    for pair in 0..pairs {
                        let (h, d) = if pair % 2 == 0 {
                            let h = timed(q, &corpus, &order, rounds, |a, b| kind.highway(a, b));
                            let d = timed(q, &corpus, &order, rounds, |a, b| native.call(a, b));
                            (h, d)
                        } else {
                            let d = timed(q, &corpus, &order, rounds, |a, b| native.call(a, b));
                            let h = timed(q, &corpus, &order, rounds, |a, b| kind.highway(a, b));
                            (h, d)
                        };
                        let hn = h.0 * 1e9 / operations as f64;
                        let dn = d.0 * 1e9 / operations as f64;
                        hs.push(hn);
                        ds.push(dn);
                        ratios.push(dn / hn);
                        samples.push(json!({
                            "pair": pair,
                            "order": if pair % 2 == 0 { "highway,diskann" } else { "diskann,highway" },
                            "highway_seconds": h.0,
                            "diskann_seconds": d.0,
                            "highway_ns_per_distance": hn,
                            "diskann_ns_per_distance": dn,
                            "highway_checksum": h.1,
                            "diskann_checksum": d.1,
                        }));
                    }
                    let ratio = median(ratios.iter().copied());
                    eprintln!(
                        "{dim:4}D {:17} offset={} count={count:4}: Highway {:.2} ns, DiskANN {:.2} ns, native/Highway {ratio:.3}x",
                        kind.name(), offset * 4, median(hs.iter().copied()), median(ds.iter().copied())
                    );
                    report["cases"].as_array_mut().ok_or("invalid report")?.push(json!({
                        "dimension": dim,
                        "metric": kind.name(),
                        "alignment_offset_bytes": offset * 4,
                        "corpus_count": count,
                        "logical_input_bytes": (count + 1) * dim * 4,
                        "allocated_corpus_bytes": corpus.storage.len() * 4,
                        "input_fnv1a64": input_fingerprint(q, &corpus, &order),
                        "operations_per_sample": operations,
                        "highway_median_ns": median(hs),
                        "diskann_median_ns": median(ds),
                        "median_paired_native_over_highway": ratio,
                        "paired_ratio_min": ratios.iter().copied().fold(f64::INFINITY, f64::min),
                        "paired_ratio_max": ratios.iter().copied().fold(f64::NEG_INFINITY, f64::max),
                        "numerical_checks": checks.json(),
                        "samples": samples,
                    }));
                    persist(&mut file, &report)?;
                }
            }
        }
    }
    report["status"] = json!("complete");
    persist(&mut file, &report)?;
    Ok(())
}
